data.query:
query Query($where: InventoryWhereInput, $orderBy: [InventoryOrderByInput!], $first: Int, $after: String) {
  inventory(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        quantity {
          value unit {code}
        }
        location {
          id
          name
        }
        product {id name}
        productStrategyProcessId
      }
    }
  }
}

query getShipmentData($where: ShipmentWhereInput, $orderBy: [ShipmentOrderByInput!], $first: Int, $after: String) {
  shipment(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        number
        shipmentLines(where:{shipmentLineStageId:{_eq:"New"}}) {
          edges {
            node {
              id
              andonRequests(where:{andonStageId: {_eq:"New"}}) {
                edges {
                  node {
                    id
                    number
                    acknowledgedByUserId
                    acknowledgedAt
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}

