data.query:
query Query($l: ShipmentLineWhereInput, $a: AndonRequestWhereInput) {
  line:shipmentLine(where: $l) {
    edges {
      node {
        id
        loadedQuantity {
          value
          unitId
        }
        quantity {
          value
          unitId
        }
        shippedQuantity {
          value
          unitId
        }
        stagedQuantity {
          value
          unitId
        }
        shipment {
        number
          shipmentStageId
        }
        shipmentId
        shipmentLineStageId
        productId
        shipmentLineInventory {
          edges {
            node {
              inventory {
                id
                quantity {
                  value
                  unitId
                }
                inventoryStatusId
              }
            }
          }
        }
        andonRequests(where:$a) {
          edges {
            node {
              id
              quantity {
                value
                unitId
              }
              inventory {
                edges {node{
                  id 
                  complete
                  loaded
                  inventory {
                    id
                    number
                    quantity {value unitId}
                  }
                }}
              }
              andonStageId
              destinationLocationId
            }
          }
        }
      }
    }
  }
}

query Inventory( 
  $whereI:InventoryWhereInput!
) {

	inventory(where:$whereI, first:1) {
    edges {node {
      id
      number
      productId
      productStrategyProcess{
        id

        productStrategy{
          product {id name}
        }
      }
      location {
        id
        name
      }
      quantity {
        value
        unit {id code}
      }
      inventoryStatus {
        splitPrevent

        id
      }
      masterInventory {
        id
        active
        allowUnload
      }
      lotId
      workOrderProcessId
      workOrderId
      receiptLineId
      supplierId
      packagingMaterialId
      kanbanCardId
      inventoryTypeId
      grossWeight
      netWeight
      tareWeight
      theoreticalWeight
      weightUnitId

      andonRequestInventory {total}
      shipmentLineInventories {total}
    }}
  }
}

query Query($where: InventoryWhereInput) {
  inventory(where: $where, first: 1) {
    edges {
      node {
        number
      }
    }
  }
}

data.transform:
(

  $L := $state.context.LOCAL;
  $i := $L.inventory;
    $a := $state.context.REQUEST.DATA.andon[shipmentLine.product.id=$i.productId];
  {

    "ar": $a.{
      "update": {
        "andonStageId": "In Process"
      }, "where": {
        "id": id
      }
    },
    "iu": $i.{
      "update": {
        "inventoryStatusId": "Picked",
        "masterInventoryId": null
      }, "where": {
        "id": id
      }
    },
    "ai": {
      "create": {
        "inventoryId": $i.id,
        "loaded": true,
        "andonRequestId": $a.id
      }
    },
    "it": $i.(
      $q := {
        "value": quantity.value,
        "unitId": quantity.unit.id
      };
      {
        "create": {
          "sourceQuantity": $q,
          "customData": $state.context.CLAIMS ? $state.context.CLAIMS : $state.claims,
          "destinationQuantity": $q,
          "sourceInventoryId":id,
          "destinationInventoryId":id,
          "sourceLocationId": location.id,
          "destinationLocationId": location.id,
          "sourceInventoryStatusId": inventoryStatus.id,
          "destinationInventoryStatusId": "Picked",
          "sourceLotId": lotId,
          "destinationLotId": lotId,
          "sourceProductId":productId,
          "destinationProductId":productId,
          "sourceProductStrategyProcessId":productStrategyProcess.id,
          "destinationProductStrategyProcessId":productStrategyProcess.id,
          "sourceWorkOrderProcessId": workOrderProcessId,
          "destinationWorkOrderProcessId": workOrderProcessId,
          "sourceMasterInventoryId":masterInventory.id,
          "destinationMasterInventoryId":null,
          "statusId": "Informational",
          "transactionTypeId": "Shipment Pick"
        }
      }
    )
  }
)

